class BitField {
    constructor(size) {
        const numWords = Math.ceil(size / 32);
        this.a = new Uint32Array(numWords);
    }
    get(index) {
        const arrayIndex = (index / 32) | 0;
        const bit = index % 32;
        return (this.a[arrayIndex] & (1 << bit)) !== 0;
    }
    set(index, newState) {
        const arrayIndex = (index / 32) | 0;
        const bit = index % 32;
        const value = this.a[arrayIndex];
        if (newState) {
            this.a[arrayIndex] = value | (1 << bit);
        }
        else {
            this.a[arrayIndex] = value & ~(1 << bit);
        }
    }
}
